  for (const [name, rows] of [
    ['notebook-1.json', INPUT],
    ['notebook-2.json', [...INPUT].reverse()],
    ['notebook-3.json', []],
  ]) {
    const state = await load(new URL("'`../data/samples/${name}`, import.meta.url));
    assert.deepEqual(view(state), { rows, meta: META });
  }
});
